// Сгенерировано scripts/embed-assets.mjs — не редактировать вручную.
// Источники: python/*.py, swift/*.swift
export const EMBEDDED_ASSETS: Record<string, string> = {
  "voiced.py": "\"\"\"Демон распознавания: держит модель в памяти между запросами.\n\nХолодная загрузка модели стоит десятки секунд, а голосовой ввод должен\nотвечать за секунды, поэтому распознаёт не разовый процесс, а демон на\nunix-сокете. Он переживает перезагрузку воркера плагина и сам выходит после\nпростоя.\n\nПротокол — JSON-строки: {\"op\": \"transcribe\" | \"ping\" | \"shutdown\", ...}.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport signal\nimport socket\nimport sys\nimport threading\nimport time\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nfrom engines import ENGINES, EngineError, TranscriptionRequest  # noqa: E402\n\nIDLE_TIMEOUT_SECONDS = float(os.environ.get(\"VOICE_INPUT_IDLE_TIMEOUT\", \"0\"))  # 0 = не выходить\nSOCKET_BACKLOG = 8\n\n_engines: dict[str, object] = {}\n_lock = threading.Lock()\n_last_activity = time.monotonic()\n\n\ndef _engine(engine_id: str):\n    engine = _engines.get(engine_id)\n    if engine is None:\n        factory = ENGINES.get(engine_id)\n        if factory is None:\n            raise EngineError(f\"Неизвестный движок: {engine_id}\")\n        engine = factory()\n        _engines[engine_id] = engine\n    return engine\n\n\ndef _handle(request: dict) -> dict:\n    global _last_activity\n    _last_activity = time.monotonic()\n    op = request.get(\"op\")\n\n    if op == \"ping\":\n        return {\"ok\": True, \"loaded\": sorted(_engines)}\n\n    if op == \"warmup\":\n        engine = _engine(str(request[\"engine\"]))\n        with _lock:\n            engine.warmup(str(request.get(\"model\") or \"\"))\n        return {\"ok\": True}\n\n    if op == \"transcribe\":\n        engine_id = str(request[\"engine\"])\n        engine = _engine(engine_id)\n        language = request.get(\"language\") or None\n        started = time.monotonic()\n        with _lock:  # модели не рассчитаны на параллельные прогоны\n            text = engine.transcribe(\n                TranscriptionRequest(\n                    audio_path=Path(str(request[\"audioPath\"])),\n                    model=str(request.get(\"model\") or \"\"),\n                    language=None if language in (None, \"auto\") else str(language),\n                    prompt=request.get(\"prompt\") or None,\n                )\n            )\n        return {\n            \"ok\": True,\n            \"text\": text,\n            \"engine\": engine_id,\n            \"durationMs\": int((time.monotonic() - started) * 1000),\n        }\n\n    if op == \"shutdown\":\n        return {\"ok\": True, \"shutdown\": True}\n\n    raise EngineError(f\"Неизвестная операция: {op}\")\n\n\ndef _serve_client(connection: socket.socket) -> bool:\n    \"\"\"Обслужить одно соединение. Возвращает True, если демон просили выйти.\"\"\"\n    with connection:\n        connection.settimeout(3600)\n        buffer = b\"\"\n        while not buffer.endswith(b\"\\n\"):\n            chunk = connection.recv(65536)\n            if not chunk:\n                return False\n            buffer += chunk\n        try:\n            request = json.loads(buffer.decode(\"utf-8\"))\n            response = _handle(request)\n        except EngineError as error:\n            response = {\"ok\": False, \"code\": \"request_failed\", \"message\": str(error)}\n        except Exception as error:  # noqa: BLE001 — любой сбой возвращаем клиенту\n            response = {\"ok\": False, \"code\": \"request_failed\", \"message\": f\"{type(error).__name__}: {error}\"}\n        connection.sendall((json.dumps(response, ensure_ascii=False) + \"\\n\").encode(\"utf-8\"))\n        return bool(response.get(\"shutdown\"))\n\n\ndef _idle_watchdog(server: socket.socket, socket_path: Path) -> None:\n    while True:\n        time.sleep(30)\n        if IDLE_TIMEOUT_SECONDS <= 0:\n            continue\n        if time.monotonic() - _last_activity > IDLE_TIMEOUT_SECONDS:\n            server.close()\n            socket_path.unlink(missing_ok=True)\n            os.kill(os.getpid(), signal.SIGTERM)\n            return\n\n\ndef main() -> int:\n    if len(sys.argv) < 2:\n        print(\"usage: voiced.py <socket-path>\", file=sys.stderr)\n        return 2\n    socket_path = Path(sys.argv[1])\n    socket_path.parent.mkdir(parents=True, exist_ok=True)\n    socket_path.unlink(missing_ok=True)\n\n    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    server.bind(str(socket_path))\n    server.listen(SOCKET_BACKLOG)\n    os.chmod(socket_path, 0o600)\n    print(json.dumps({\"event\": \"listening\", \"socket\": str(socket_path)}), flush=True)\n\n    threading.Thread(target=_idle_watchdog, args=(server, socket_path), daemon=True).start()\n\n    try:\n        while True:\n            try:\n                connection, _ = server.accept()\n            except OSError:\n                break\n            try:\n                if _serve_client(connection):\n                    break\n            except Exception as error:  # noqa: BLE001 — один клиент не роняет демон\n                print(json.dumps({\"event\": \"error\", \"message\": str(error)}), flush=True)\n    finally:\n        server.close()\n        socket_path.unlink(missing_ok=True)\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n",
  "engines.py": "\"\"\"Движки распознавания: Whisper (MLX) и GigaAM v3.\n\nWhisper — многоязычный и быстрый на Apple Silicon. GigaAM — русский от Сбера,\nв варианте v3_e2e_rnnt даёт пунктуацию и нормализацию из коробки, но\n`transcribe` принимает не больше 25 секунд, поэтому длинное аудио режется\nздесь по паузам.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport subprocess\nimport tempfile\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nGIGAAM_MODEL = \"v3_e2e_rnnt\"\nGIGAAM_CHUNK_SECONDS = 22.0\nGIGAAM_SAMPLE_RATE = 16000\n\n\n@dataclass\nclass TranscriptionRequest:\n    audio_path: Path\n    model: str\n    language: str | None\n    prompt: str | None\n\n\nclass EngineError(RuntimeError):\n    \"\"\"Движок не смог распознать запись; сообщение уходит пользователю.\"\"\"\n\n\nclass WhisperEngine:\n    \"\"\"mlx-whisper: модель кешируется библиотекой, повторные вызовы быстрые.\"\"\"\n\n    id = \"whisper\"\n\n    def __init__(self) -> None:\n        self._loaded_model: str | None = None\n\n    def warmup(self, model: str) -> None:\n        import mlx_whisper\n        import numpy as np\n\n        mlx_whisper.transcribe(np.zeros(GIGAAM_SAMPLE_RATE, dtype=np.float32), path_or_hf_repo=model)\n        self._loaded_model = model\n\n    def transcribe(self, request: TranscriptionRequest) -> str:\n        import mlx_whisper\n\n        options: dict[str, object] = {\n            \"path_or_hf_repo\": request.model,\n            # Whisper дописывает на тишине заученные хвосты вроде «Редактор\n            # субтитров…». Без опоры на предыдущий отрезок это почти исчезает,\n            # а связность короткой диктовки не страдает.\n            \"condition_on_previous_text\": False,\n        }\n        if request.language:\n            options[\"language\"] = request.language\n        if request.prompt:\n            options[\"initial_prompt\"] = request.prompt\n        result = mlx_whisper.transcribe(str(request.audio_path), **options)\n        self._loaded_model = request.model\n        return str(result.get(\"text\") or \"\").strip()\n\n\nclass GigaamEngine:\n    \"\"\"GigaAM v3 end-to-end: русский с пунктуацией, длинное аудио режем сами.\n\n    На Apple Silicon модель считается на GPU через MPS. Не все операции RNNT\n    там реализованы, поэтому при сбое движок один раз откатывается на CPU и\n    дальше работает на нём — молча падать посреди диктовки он не должен.\n    \"\"\"\n\n    id = \"gigaam\"\n\n    def __init__(self) -> None:\n        self._model = None\n        self._vad = None\n        self._device = None\n\n    def warmup(self, model: str) -> None:\n        self._ensure_model()\n\n    def _preferred_device(self) -> str:\n        import torch\n\n        if torch.backends.mps.is_available():\n            return \"mps\"\n        return \"cpu\"\n\n    def _ensure_model(self):\n        if self._model is None:\n            import gigaam\n\n            device = self._device or self._preferred_device()\n            try:\n                # fp16 на MPS даёт заметный выигрыш, на CPU он не поддержан.\n                self._model = gigaam.load_model(\n                    GIGAAM_MODEL, device=device, fp16_encoder=device == \"mps\"\n                )\n                self._device = device\n            except Exception:\n                if device == \"cpu\":\n                    raise\n                self._model = gigaam.load_model(GIGAAM_MODEL, device=\"cpu\", fp16_encoder=False)\n                self._device = \"cpu\"\n        return self._model\n\n    def _transcribe_chunk(self, model, chunk: Path) -> str:\n        \"\"\"Один кусок. Сбой на MPS переводит движок на CPU и повторяет попытку.\"\"\"\n        try:\n            return str(model.transcribe(str(chunk))).strip()\n        except (NotImplementedError, RuntimeError):\n            if self._device != \"mps\":\n                raise\n            import gigaam\n\n            self._model = gigaam.load_model(GIGAAM_MODEL, device=\"cpu\", fp16_encoder=False)\n            self._device = \"cpu\"\n            return str(self._model.transcribe(str(chunk))).strip()\n\n    def transcribe(self, request: TranscriptionRequest) -> str:\n        model = self._ensure_model()\n        wav_path = _to_wav(request.audio_path)\n        try:\n            chunks = self._split(wav_path)\n            texts: list[str] = []\n            for chunk in chunks:\n                text = self._transcribe_chunk(model, chunk)\n                if text:\n                    texts.append(text)\n            return \" \".join(texts).strip()\n        finally:\n            _cleanup(wav_path, keep=request.audio_path)\n\n    def _split(self, wav_path: Path) -> list[Path]:\n        \"\"\"Нарезать по речевым сегментам: GigaAM.transcribe берёт до 25 секунд.\"\"\"\n        import soundfile as sf\n\n        audio, sample_rate = sf.read(str(wav_path), dtype=\"float32\")\n        if audio.ndim > 1:\n            audio = audio.mean(axis=1)\n        limit = int(GIGAAM_CHUNK_SECONDS * sample_rate)\n        if len(audio) <= limit:\n            return [wav_path]\n\n        boundaries = self._speech_boundaries(audio, sample_rate, limit)\n        parts: list[Path] = []\n        for index, (start, end) in enumerate(boundaries):\n            part = wav_path.with_name(f\"{wav_path.stem}-{index:03d}.wav\")\n            sf.write(str(part), audio[start:end], sample_rate)\n            parts.append(part)\n        return parts\n\n    def _speech_boundaries(self, audio, sample_rate: int, limit: int) -> list[tuple[int, int]]:\n        \"\"\"Границы кусков: по паузам, найденным Silero VAD, иначе равными долями.\"\"\"\n        try:\n            if self._vad is None:\n                from silero_vad import load_silero_vad\n\n                self._vad = load_silero_vad()\n            from silero_vad import get_speech_timestamps\n\n            import torch\n\n            timestamps = get_speech_timestamps(\n                torch.from_numpy(audio), self._vad, sampling_rate=sample_rate\n            )\n        except Exception:\n            timestamps = []\n\n        if not timestamps:\n            return [(start, min(start + limit, len(audio))) for start in range(0, len(audio), limit)]\n\n        boundaries: list[tuple[int, int]] = []\n        current_start = timestamps[0][\"start\"]\n        current_end = timestamps[0][\"end\"]\n        for segment in timestamps[1:]:\n            if segment[\"end\"] - current_start > limit:\n                boundaries.append((current_start, current_end))\n                current_start = segment[\"start\"]\n            current_end = segment[\"end\"]\n        boundaries.append((current_start, current_end))\n        # Слишком длинный отдельный сегмент речи без пауз всё равно режем жёстко.\n        result: list[tuple[int, int]] = []\n        for start, end in boundaries:\n            while end - start > limit:\n                result.append((start, start + limit))\n                start += limit\n            result.append((start, end))\n        return result\n\n\ndef _to_wav(source: Path) -> Path:\n    \"\"\"GigaAM ждёт 16 кГц моно; браузер присылает webm/opus.\"\"\"\n    if source.suffix.lower() == \".wav\":\n        return source\n    target = Path(tempfile.mkdtemp(prefix=\"voice-input-\")) / \"audio.wav\"\n    process = subprocess.run(\n        [\n            \"ffmpeg\", \"-nostdin\", \"-y\", \"-i\", str(source),\n            \"-ar\", str(GIGAAM_SAMPLE_RATE), \"-ac\", \"1\", str(target),\n        ],\n        capture_output=True,\n        check=False,\n    )\n    if process.returncode != 0 or not target.exists():\n        raise EngineError(f\"ffmpeg не смог подготовить аудио: {process.stderr.decode('utf-8', 'replace')[-400:]}\")\n    return target\n\n\ndef _cleanup(wav_path: Path, keep: Path) -> None:\n    if wav_path == keep:\n        return\n    directory = wav_path.parent\n    for item in directory.glob(\"*.wav\"):\n        item.unlink(missing_ok=True)\n    try:\n        directory.rmdir()\n    except OSError:\n        pass\n\n\nENGINES = {\"whisper\": WhisperEngine, \"gigaam\": GigaamEngine}\n",
  "download.py": "\"\"\"Предзагрузка модели с прогрессом.\n\nПечатает в stdout строки JSON: {\"event\": \"progress\", \"percent\": N, ...} и в\nконце {\"event\": \"done\"} либо {\"event\": \"error\", \"message\": ...}. Хост читает их\nпострочно и превращает в сигналы, которые видит интерфейс.\n\nМолчаливая ленивая загрузка при первой фразе — плохой опыт: пользователь ждёт\nминуты и не знает, скачивается модель или всё сломалось.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nimport time\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nREPORT_INTERVAL_SECONDS = 0.5\n\n\ndef emit(payload: dict) -> None:\n    print(json.dumps(payload, ensure_ascii=False), flush=True)\n\n\nclass ProgressTqdm:\n    \"\"\"Подменяет tqdm внутри huggingface_hub, чтобы отдавать проценты наружу.\"\"\"\n\n    _total_bytes = 0\n    _done_bytes = 0\n    _last_report = 0.0\n    # Размер известен заранее — счётчики отдельных файлов его не меняют.\n    _report_total_known = False\n\n    def __init__(self, *args, **kwargs):\n        self.total = kwargs.get(\"total\") or 0\n        self.n = 0\n        self.desc = kwargs.get(\"desc\") or \"\"\n        # huggingface_hub заводит счётчики и на файлы, и на байты. В общий\n        # прогресс идут только байтовые, иначе «1 из 4 файлов» превращается\n        # в 25 % задолго до конца загрузки.\n        self.counts_bytes = kwargs.get(\"unit\") == \"B\"\n        if self.counts_bytes and not ProgressTqdm._report_total_known:\n            ProgressTqdm._total_bytes += self.total\n\n    def update(self, amount: int = 1) -> None:\n        self.n += amount\n        if not self.counts_bytes:\n            return\n        ProgressTqdm._done_bytes += amount\n        now = time.monotonic()\n        if now - ProgressTqdm._last_report < REPORT_INTERVAL_SECONDS:\n            return\n        ProgressTqdm._last_report = now\n        self.report()\n\n    def report(self) -> None:\n        total = ProgressTqdm._total_bytes\n        done = ProgressTqdm._done_bytes\n        emit({\n            \"event\": \"progress\",\n            \"percent\": round(done / total * 100, 1) if total else None,\n            \"downloadedBytes\": done,\n            \"totalBytes\": total or None,\n        })\n\n    def close(self) -> None:\n        if self.counts_bytes:\n            self.report()\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *_args) -> None:\n        self.close()\n\n    def __iter__(self):\n        return iter(())\n\n    def set_description(self, *_args, **_kwargs) -> None:\n        return None\n\n    def set_postfix(self, *_args, **_kwargs) -> None:\n        return None\n\n    def refresh(self) -> None:\n        return None\n\n    def reset(self, total=None) -> None:\n        self.total = total or 0\n\n\ndef repository_size(model: str) -> int:\n    \"\"\"Суммарный размер файлов модели. Библиотека сама общий размер не сообщает.\"\"\"\n    from huggingface_hub import HfApi\n\n    try:\n        info = HfApi().model_info(model, files_metadata=True)\n    except Exception:\n        return 0\n    return sum(getattr(sibling, \"size\", None) or 0 for sibling in (info.siblings or []))\n\n\ndef download_whisper(model: str) -> None:\n    from huggingface_hub import snapshot_download\n\n    # Проценты считаются от размера репозитория. Уже скачанные файлы заново не\n    # качаются, поэтому на частично заполненном кеше прогресс доходит до конца\n    # скачком — итоговое событие всё равно ставит 100 %.\n    ProgressTqdm._total_bytes = repository_size(model)\n    ProgressTqdm._report_total_known = ProgressTqdm._total_bytes > 0\n    snapshot_download(repo_id=model, tqdm_class=ProgressTqdm)\n\n\ndef download_gigaam() -> None:\n    \"\"\"У GigaAM свой загрузчик с CDN; точных процентов он наружу не отдаёт.\"\"\"\n    import gigaam\n\n    from engines import GIGAAM_MODEL\n\n    emit({\"event\": \"progress\", \"percent\": None, \"downloadedBytes\": None, \"totalBytes\": None})\n    gigaam.load_model(GIGAAM_MODEL, device=\"cpu\", fp16_encoder=False)\n\n\ndef main() -> int:\n    if len(sys.argv) < 2:\n        emit({\"event\": \"error\", \"message\": \"usage: download.py <engine> [model]\"})\n        return 2\n    engine = sys.argv[1]\n    try:\n        if engine == \"whisper\":\n            if len(sys.argv) < 3:\n                emit({\"event\": \"error\", \"message\": \"не указана модель\"})\n                return 2\n            download_whisper(sys.argv[2])\n        elif engine == \"gigaam\":\n            download_gigaam()\n        else:\n            emit({\"event\": \"error\", \"message\": f\"У движка «{engine}» нет загружаемой модели\"})\n            return 2\n    except Exception as error:  # noqa: BLE001 — сообщение уходит пользователю\n        emit({\"event\": \"error\", \"message\": f\"{type(error).__name__}: {error}\"})\n        return 1\n    emit({\"event\": \"done\"})\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n",
};
